def solve_n(n):
    import itertools
    # We want d_i + d_j to be n(n-1)/2 distinct integers.
    # d_1 = 0, and d_2 < d_3 < ... < d_n are distinct positive integers.
    # The sums d_i + d_j (i < j) must be distinct.
    # Let's try to find such d_i.
    for d in itertools.combinations(range(1, 20), n-1):
        d_list = [0] + list(d)
        sums = set()
        for i in range(n):
            for j in range(i + 1, n):
                sums.add(d_list[i] + d_list[j])
        if len(sums) == n * (n - 1) // 2:
            # Now we need the sums to be consecutive.
            s_list = sorted(list(sums))
            if all(s_list[i] == s_list[0] + i for i in range(len(s_list))):
                return d_list
    return None

